INSERT OR IGNORE INTO subjects (id, curriculum_id, name, code, description, color_code, created_at) VALUES
('subj-caie-igcse-maths', 'curr-caie-igcse', 'Mathematics', '0580', 'Cambridge IGCSE Mathematics', '#3b82f6', strftime('%s', 'now') * 1000),
('subj-caie-igcse-addmaths', 'curr-caie-igcse', 'Additional Mathematics', '0606', 'Cambridge IGCSE Additional Mathematics', '#3b82f6', strftime('%s', 'now') * 1000),
('subj-caie-igcse-bio', 'curr-caie-igcse', 'Biology', '0610', 'Cambridge IGCSE Biology', '#10b981', strftime('%s', 'now') * 1000),
('subj-caie-igcse-ict', 'curr-caie-igcse', 'Information and Communication Technology', '0417', 'Cambridge IGCSE Information and Communication Technology', '#f59e0b', strftime('%s', 'now') * 1000),
('subj-caie-igcse-biz', 'curr-caie-igcse', 'Business Studies', '0450', 'Cambridge IGCSE Business Studies', '#6366f1', strftime('%s', 'now') * 1000),
('subj-caie-igcse-acc', 'curr-caie-igcse', 'Accounting', '0452', 'Cambridge IGCSE Accounting', '#eab308', strftime('%s', 'now') * 1000);

INSERT OR IGNORE INTO topics (id, subject_id, name, description, order_index, subtopics_count, difficulty_level, estimated_hours, created_at, updated_at) VALUES
('topic-caie-igcse-maths-01', 'subj-caie-igcse-maths', 'Number', 'Identify and calculate with types of numbers, sets, powers, roots, fractions, decimals, standard form, estimation, limits of accuracy, ratio, rates, percentages, exponential growth, and surds.', 1, 18, 'medium', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-02', 'subj-caie-igcse-maths', 'Algebra and graphs', 'Covers algebraic manipulation, algebraic fractions, indices, linear and quadratic equations, inequalities, sequences, proportion, graphs in practical situations, sketching curves, differentiation, and functions.', 2, 13, 'hard', 16, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-03', 'subj-caie-igcse-maths', 'Coordinate geometry', 'Understand Cartesian coordinates, plot and interpret linear graphs, calculate gradients, line lengths, midpoints, and determine equations of parallel and perpendicular lines.', 3, 7, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-04', 'subj-caie-igcse-maths', 'Geometry', 'Use geometrical vocabulary, constructions, scale drawings, bearings, similarity, symmetry in 2D and 3D shapes, angle properties of intersecting lines and polygons, and circle theorems.', 4, 8, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-05', 'subj-caie-igcse-maths', 'Mensuration', 'Calculate perimeters, areas, arc lengths, sector areas, surface areas, and volumes of standard 2D and 3D shapes, compound solids, and parts of solids.', 5, 5, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-06', 'subj-caie-igcse-maths', 'Trigonometry', 'Apply Pythagoras theorem and sine, cosine, and tangent ratios in right-angled triangles, recall exact trigonometric values, sketch trigonometric graphs, and solve 2D and 3D triangle problems using sine and cosine rules.', 6, 6, 'hard', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-07', 'subj-caie-igcse-maths', 'Transformations and vectors', 'Describe and draw reflections, rotations, enlargements, and translations; calculate with column vectors, find magnitudes, and apply vectors to geometric problems.', 7, 4, 'hard', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-08', 'subj-caie-igcse-maths', 'Probability', 'Calculate probabilities of single and combined events using sample spaces, Venn diagrams, and tree diagrams, alongside estimating expected frequencies and calculating conditional probability.', 8, 4, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-maths-09', 'subj-caie-igcse-maths', 'Statistics', 'Classify, tabulate, and interpret statistical data using statistical measures, bar charts, pie charts, stem-and-leaf diagrams, scatter diagrams, cumulative frequency curves, and histograms.', 9, 7, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-01', 'subj-caie-igcse-addmaths', 'Functions', 'Understand function definitions, determine domain and range, sketch modulus transformations, determine inverse functions, and compose multiple functions.', 1, 8, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-02', 'subj-caie-igcse-addmaths', 'Quadratic functions', 'Find extrema by completing the square or differentiation, sketch parabolas, apply the discriminant to intersection problems, and solve quadratic inequalities.', 2, 5, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-03', 'subj-caie-igcse-addmaths', 'Factors of polynomials', 'Apply remainder and factor theorems to find linear factors of polynomials and solve cubic equations.', 3, 3, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-04', 'subj-caie-igcse-addmaths', 'Equations, inequalities and graphs', 'Solve equations and inequalities containing modulus terms, apply quadratic substitution techniques, and sketch cubic polynomials and their modulus transformations.', 4, 5, 'hard', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-05', 'subj-caie-igcse-addmaths', 'Simultaneous equations', 'Solve simultaneous equations in two variables algebraically where one equation is linear and one is non-linear.', 5, 1, 'medium', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-06', 'subj-caie-igcse-addmaths', 'Logarithmic and exponential functions', 'Apply laws of logarithms and change of base, analyse asymptotic behaviours of exponential and logarithmic curves, and solve exponential equations.', 6, 3, 'hard', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-07', 'subj-caie-igcse-addmaths', 'Straight-line graphs', 'Interpret linear relations, apply perpendicular and parallel conditions, solve perpendicular bisector problems, and transform non-linear equations into linear straight-line form.', 7, 4, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-08', 'subj-caie-igcse-addmaths', 'Coordinate geometry of the circle', 'Determine circle equations from centres and radii, solve circle-line intersections and tangents, and analyse intersections between two circles.', 8, 4, 'hard', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-09', 'subj-caie-igcse-addmaths', 'Circular measure', 'Solve geometric problems involving angles measured in radians, circular arc lengths, and areas of sectors.', 9, 1, 'medium', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-10', 'subj-caie-igcse-addmaths', 'Trigonometry', 'Work with six trigonometric functions across all quadrants, evaluate amplitude and periodicity, apply Pythagorean identities, solve trigonometric equations, and prove identities.', 10, 6, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-11', 'subj-caie-igcse-addmaths', 'Permutations and combinations', 'Distinguish between permutations and combinations, apply factorial notations, and solve complex arrangement and selection problems.', 11, 3, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-12', 'subj-caie-igcse-addmaths', 'Series', 'Expand expressions using the binomial theorem, find specific expansion coefficients, and solve problems with arithmetic, geometric, and infinite convergent progressions.', 12, 5, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-13', 'subj-caie-igcse-addmaths', 'Vectors in two dimensions', 'Represent vectors using various notations, calculate magnitudes and unit vectors, perform vector arithmetic, and compose relative velocities.', 13, 4, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-addmaths-14', 'subj-caie-igcse-addmaths', 'Calculus', 'Differentiate standard functions, apply product, quotient, and chain rules to tangents and stationary points, evaluate indefinite and definite integrals, calculate plane areas, and solve rectilinear kinematics problems.', 14, 15, 'hard', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-01', 'subj-caie-igcse-bio', 'Characteristics and classification of living organisms', 'Describes the defining characteristics of living organisms, principles and uses of biological classification, binomial nomenclature, dichotomous keys, and distinguishing features of major taxonomic groups.', 1, 3, 'easy', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-02', 'subj-caie-igcse-bio', 'Organisation of the organism', 'Details the structures and organelles of plant, animal, and bacterial cells, examines specialised cells and levels of biological organisation, and calculates specimen magnification.', 2, 2, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-03', 'subj-caie-igcse-bio', 'Movement into and out of cells', 'Examines the mechanisms of passive diffusion, water potential changes during osmosis, and active transport across semi-permeable cell membranes.', 3, 3, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-04', 'subj-caie-igcse-bio', 'Biological molecules', 'Outlines the synthesis and structures of carbohydrates, lipids, proteins, and the DNA double helix, alongside laboratory chemical food tests.', 4, 1, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-05', 'subj-caie-igcse-bio', 'Enzymes', 'Explains enzymes functioning as biological catalysts, active site complementary binding, and the effects of temperature and pH denaturation.', 5, 1, 'medium', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-06', 'subj-caie-igcse-bio', 'Plant nutrition', 'Details the chemical reactions of photosynthesis, the role of chlorophyll and light, environmental limiting factors, mineral requirements, and internal leaf anatomy adaptations.', 6, 2, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-07', 'subj-caie-igcse-bio', 'Human nutrition', 'Covers balanced diets, dietary deficiencies, the human digestive system, mechanical breakdown, enzyme-driven chemical breakdown, and intestinal absorption by villi.', 7, 5, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-08', 'subj-caie-igcse-bio', 'Transport in plants', 'Examines the functions and structures of xylem and phloem, root water absorption pathways, the transpiration pull, and phloem translocation from sources to sinks.', 8, 4, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-09', 'subj-caie-igcse-bio', 'Transport in animals', 'Surveys single and double circulatory systems, heart anatomy and cardiac function, coronary heart disease, blood vessel structures, and blood components.', 9, 4, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-10', 'subj-caie-igcse-bio', 'Diseases and immunity', 'Details pathogen transmission routes, body defences, active and passive immunity mechanisms, antibody specificity, vaccination principles, and cholera pathology.', 10, 1, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-11', 'subj-caie-igcse-bio', 'Gas exchange in humans', 'Covers the anatomy of the breathing system, adaptations of gas exchange surfaces, physical mechanics of lung ventilation, and the impact of exercise.', 11, 1, 'medium', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-12', 'subj-caie-igcse-bio', 'Respiration', 'Explores cellular energy utilisation, aerobic respiration pathways, anaerobic respiration in yeast and human muscle tissues, and the physiological oxygen debt.', 12, 3, 'medium', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-13', 'subj-caie-igcse-bio', 'Excretion in humans', 'Outlines excretory organs, gross anatomy and histology of the kidney, nephron filtration and selective reabsorption, deamination in the liver, and urea toxicity.', 13, 1, 'hard', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-14', 'subj-caie-igcse-bio', 'Coordination and response', 'Surveys mammalian nervous pathways, reflex arcs, synaptic transmission, eye anatomy and accommodation, endocrine systems, temperature/glucose homeostasis, and plant tropic responses.', 14, 5, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-15', 'subj-caie-igcse-bio', 'Drugs', 'Defines medicinal drugs, explores the therapeutic action of antibiotics against bacterial pathogens, and discusses the development of antibiotic resistance.', 15, 1, 'easy', 3, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-16', 'subj-caie-igcse-bio', 'Reproduction', 'Contrasts asexual and sexual reproduction, details plant floral anatomy, pollination, and seed germination, and examines human reproductive anatomy, gametes, and the menstrual cycle.', 16, 6, 'hard', 9, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-17', 'subj-caie-igcse-bio', 'Inheritance', 'Examines chromosome structure, DNA coding, transcription/translation overviews, mitosis, meiosis, monohybrid crosses, Punnett squares, codominance, and sex-linkage.', 17, 4, 'hard', 9, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-18', 'subj-caie-igcse-bio', 'Variation and selection', 'Explores continuous and discontinuous variation, mutations, ecological adaptations, natural selection mechanisms, and artificial selective breeding.', 18, 3, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-19', 'subj-caie-igcse-bio', 'Organisms and their environment', 'Covers ecosystem energy flow, trophic food chains and ecological pyramids, biogeochemical carbon and nitrogen cycling, and sigmoid population growth curves.', 19, 4, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-20', 'subj-caie-igcse-bio', 'Human influences on ecosystems', 'Assesses food production impacts, intensive farming, deforestation, aquatic eutrophication, plastic pollution, greenhouse gas warming, and conservation strategies.', 20, 4, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-bio-21', 'subj-caie-igcse-bio', 'Biotechnology and genetic modification', 'Explores the industrial use of bacteria, industrial fermenters, food enzymes, and the genetic modification process using restriction enzymes and plasmids.', 21, 3, 'hard', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-01', 'subj-caie-igcse-ict', 'Types and components of computer systems', 'Examines internal and external computer hardware, system software vs application software, operating systems, and emerging technologies.', 1, 5, 'easy', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-02', 'subj-caie-igcse-ict', 'Input and output devices', 'Analyses characteristics, operations, and suitable scenarios for manual input devices, automated direct data entry hardware, and output devices.', 2, 3, 'easy', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-03', 'subj-caie-igcse-ict', 'Storage devices and media', 'Explores magnetic, optical, and solid-state data storage media and drives, comparing their capacities, relative costs, and data access speeds.', 3, 1, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-04', 'subj-caie-igcse-ict', 'Networks and the effects of using them', 'Covers networking devices, Wi-Fi, Bluetooth, cloud computing models, network topologies (LAN, WLAN, WAN), transfer security, and electronic conferencing.', 4, 2, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-05', 'subj-caie-igcse-ict', 'The effects of using IT', 'Examines lifestyle impacts and transport shifts caused by microprocessor-controlled smart devices, along with prolonged workstation ergonomic health issues.', 5, 2, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-06', 'subj-caie-igcse-ict', 'ICT applications', 'Surveys major practical applications including communication media, modelling, automated industrial robotics, school systems, booking systems, banking, medicine, expert systems, and retail.', 6, 11, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-07', 'subj-caie-igcse-ict', 'The systems life cycle', 'Breaks down the full systems development lifecycle across research analysis, design planning, testing methods, changeover implementations, documentation, and evaluation.', 7, 6, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-08', 'subj-caie-igcse-ict', 'Safety and security', 'Addresses physical hazards in IT workplaces, eSafety best practices across digital platforms, data threats (malware, phishing, hacking), and security countermeasures.', 8, 3, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-09', 'subj-caie-igcse-ict', 'Audience', 'Discusses identifying target audience characteristics to create fit-for-purpose solutions and outlines digital copyright principles and antipiracy controls.', 9, 2, 'easy', 3, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-10', 'subj-caie-igcse-ict', 'Communication', 'Covers formal email etiquette, spam management, web search engine mechanics, internet protocol functions, and evaluating internet content validity.', 10, 2, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-11', 'subj-caie-igcse-ict', 'File management', 'Reviews structured hierarchical folder filing, proprietary vs generic file extensions, and compression algorithms used for file transmission.', 11, 2, 'easy', 3, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-12', 'subj-caie-igcse-ict', 'Images', 'Applies practical manipulation techniques including cropping, aspect ratios, transformations, brightness adjustments, layering, and reducing file sizes via resolution.', 12, 1, 'easy', 3, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-13', 'subj-caie-igcse-ict', 'Layout', 'Covers page text editing, object placement, wrap settings, table creation, cell formatting, and consistent header and footer insertions.', 13, 3, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-14', 'subj-caie-igcse-ict', 'Styles', 'Creates, edits, and applies consistent corporate house styles across typography, paragraphs, alignments, indents, and bulleted lists.', 14, 1, 'easy', 3, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-15', 'subj-caie-igcse-ict', 'Proofing', 'Uses automated spellcheckers, establishes data validation routines, and applies visual proofreading strategies to eliminate errors.', 15, 2, 'easy', 3, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-16', 'subj-caie-igcse-ict', 'Graphs and charts', 'Builds charts from selected data sets, formats axis scales, adds secondary axes, applies value labels, and isolates pie chart sectors.', 16, 1, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-17', 'subj-caie-igcse-ict', 'Document production', 'Configures margins, page orientations, column breaks, gutters, paragraph tabs, navigation bookmarks, and hyperlinked elements.', 17, 1, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-18', 'subj-caie-igcse-ict', 'Databases', 'Configures relational schemas, establishes data types, primary and foreign keys, writes search queries with logical operators, and designs data forms and reports.', 18, 3, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-19', 'subj-caie-igcse-ict', 'Presentations', 'Configures master slides, inserts multimedia, controls animation and slide transitions, adds presenter notes, and sets carousel playback.', 19, 1, 'easy', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-20', 'subj-caie-igcse-ict', 'Spreadsheets', 'Creates data models using formulas, absolute/relative cell referencing, lookup functions, nested logic, conditional formatting, and custom print layouts.', 20, 3, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-ict-21', 'subj-caie-igcse-ict', 'Website authoring', 'Builds HTML webpage structures across content and presentation layers, inserts tables and media, writes metadata, and attaches CSS stylesheets.', 21, 3, 'hard', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-biz-01', 'subj-caie-igcse-biz', 'Understanding business activity', 'Introduces the nature of business activity, sector classifications, entrepreneurship, measuring enterprise growth and size, business ownership structures, and stakeholder objectives.', 1, 5, 'easy', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-biz-02', 'subj-caie-igcse-biz', 'People in business', 'Examines motivational theories, financial and non-financial rewards, organisational hierarchy, leadership styles, trade unions, recruitment, training, and workplace communication.', 2, 4, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-biz-03', 'subj-caie-igcse-biz', 'Marketing', 'Covers identifying customer needs, market segmentation, market research methods, the marketing mix (product, price, place, promotion), and foreign market strategies.', 3, 4, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-biz-04', 'subj-caie-igcse-biz', 'Operations management', 'Details production methods, lean manufacturing, inventory management, economies of scale, break-even analysis, quality assurance, and factors influencing business location.', 4, 4, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-biz-05', 'subj-caie-igcse-biz', 'Financial information and decisions', 'Explores internal and external sources of finance, cash-flow forecasting, working capital, income statements, statements of financial position, and financial ratio analysis.', 5, 5, 'hard', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-biz-06', 'subj-caie-igcse-biz', 'External influences on business activity', 'Analyses economic business cycles, government fiscal/monetary policies, environmental sustainability, business ethics, globalisation, multinational corporations, and exchange rate fluctuations.', 6, 3, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-acc-01', 'subj-caie-igcse-acc', 'The fundamentals of accounting', 'Explains the difference between book-keeping and accounting, the purposes of measuring profit and loss, and how to apply the accounting equation.', 1, 2, 'easy', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-acc-02', 'subj-caie-igcse-acc', 'Sources and recording of data', 'Covers the double entry system, division of the ledger, business source documents, books of prime entry, and the imprest petty cash system.', 2, 3, 'medium', 9, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-acc-03', 'subj-caie-igcse-acc', 'Verification of accounting records', 'Focuses on the preparation and limitations of trial balances, suspense accounts for correction of errors, bank reconciliation statements, and sales/purchases control accounts.', 3, 4, 'hard', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-acc-04', 'subj-caie-igcse-acc', 'Accounting procedures', 'Distinguishes between capital and revenue transactions, calculates depreciation and asset disposals, accounts for accruals and prepayments, irrecoverable debts, and inventory valuations.', 4, 5, 'hard', 11, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-acc-05', 'subj-caie-igcse-acc', 'Preparation of financial statements', 'Prepares statements of profit or loss and statements of financial position for sole traders, partnerships, limited companies, manufacturing accounts, clubs, and incomplete records.', 5, 6, 'hard', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-acc-06', 'subj-caie-igcse-acc', 'Analysis and interpretation', 'Calculates and evaluates profitability, liquidity, and efficiency accounting ratios, and examines inter-firm comparison and the limitations of financial statements.', 6, 5, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-acc-07', 'subj-caie-igcse-acc', 'Accounting concepts and modern practice', 'Applies fundamental accounting concepts, explores ethical standards for accounting professionals, and assesses the role of digital applications and sustainable storage.', 7, 3, 'easy', 6, strftime('%s','now')*1000, strftime('%s','now')*1000);

INSERT OR IGNORE INTO subjects (id, curriculum_id, name, code, description, color_code, created_at) VALUES
('subj-caie-igcse-phys', 'curr-caie-igcse', 'Physics', '0625', 'Cambridge IGCSE Physics', '#8b5cf6', strftime('%s', 'now') * 1000),
('subj-caie-igcse-chem', 'curr-caie-igcse', 'Chemistry', '0620', 'Cambridge IGCSE Chemistry', '#ec4899', strftime('%s', 'now') * 1000),
('subj-caie-igcse-cs', 'curr-caie-igcse', 'Computer Science', '0478', 'Cambridge IGCSE Computer Science', '#f59e0b', strftime('%s', 'now') * 1000),
