INSERT OR IGNORE INTO topics (id, subject_id, name, description, order_index, subtopics_count, difficulty_level, estimated_hours, created_at, updated_at) VALUES
('topic-caie-igcse-phys-01', 'subj-caie-igcse-phys', 'Motion, forces and energy', 'Examines physical measurement, kinematics, mass and weight, density, forces, momentum, energy conservation, work, power, and pressure in fluids.', 1, 8, 'hard', 15, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-phys-02', 'subj-caie-igcse-phys', 'Thermal physics', 'Covers the kinetic particle model, gas laws, thermal expansion, specific heat capacity, changes of state, and thermal transfer mechanisms.', 2, 3, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-phys-03', 'subj-caie-igcse-phys', 'Waves', 'Explores transverse and longitudinal wave properties, light reflection and refraction, thin converging lenses, dispersion, the electromagnetic spectrum, and sound.', 3, 4, 'medium', 11, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-phys-04', 'subj-caie-igcse-phys', 'Electricity and magnetism', 'Covers magnetic phenomena, electric charge, circuits, electrical safety, electromagnetic induction, generators, motors, and transformers.', 4, 5, 'hard', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-phys-05', 'subj-caie-igcse-phys', 'Nuclear physics', 'Details atomic structure, alpha particle scattering, the nucleus, radioactive emissions, decay equations, half-life, and radiation safety.', 5, 2, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-phys-06', 'subj-caie-igcse-phys', 'Space physics', 'Covers planetary motion, the solar system, stellar lifecycles, nuclear fusion in stars, redshift, the expanding universe, and the Hubble constant.', 6, 2, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-01', 'subj-caie-igcse-chem', 'States of matter', 'Covers particle separation, arrangement, and motion in solids, liquids, and gases, changes of state, and gaseous diffusion.', 1, 2, 'easy', 4, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-02', 'subj-caie-igcse-chem', 'Atoms, elements and compounds', 'Explores atomic structure, electronic configurations, isotopes, ionic lattices, covalent molecules, giant covalent structures, and metallic bonding.', 2, 7, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-03', 'subj-caie-igcse-chem', 'Stoichiometry', 'Details chemical formulae construction, balancing symbol and ionic equations, molar masses, the Avogadro constant, and reacting volume calculations.', 3, 3, 'hard', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-04', 'subj-caie-igcse-chem', 'Electrochemistry', 'Examines the electrolysis of molten and aqueous ionic compounds, electrode half-equations, electroplating, and hydrogen-oxygen fuel cells.', 4, 2, 'hard', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-05', 'subj-caie-igcse-chem', 'Chemical energetics', 'Defines exothermic and endothermic reactions, reaction pathway diagrams, activation energy, and bond energy calculations.', 5, 1, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-06', 'subj-caie-igcse-chem', 'Chemical reactions', 'Covers factors affecting reaction rates, collision theory, reversible reactions, Le Chatelier principles in industrial processes, and redox reactions.', 6, 4, 'hard', 11, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-07', 'subj-caie-igcse-chem', 'Acids, bases and salts', 'Details the properties of acids and bases, proton transfer, oxide classifications, salt preparation techniques, and solubility rules.', 7, 3, 'medium', 9, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-08', 'subj-caie-igcse-chem', 'The Periodic Table', 'Explores periodic trends across periods, Group I alkali metals, Group VII halogens, transition elements, and unreactive noble gases.', 8, 5, 'easy', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-09', 'subj-caie-igcse-chem', 'Metals', 'Covers physical and chemical properties of metals, alloy structures, reactivity series displacement, metal corrosion prevention, and metal extraction from ores.', 9, 6, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-10', 'subj-caie-igcse-chem', 'Chemistry of the environment', 'Examines chemical tests for water, domestic water treatment, agricultural fertilisers, air pollution sources, and greenhouse gas climate impacts.', 10, 3, 'easy', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-11', 'subj-caie-igcse-chem', 'Organic chemistry', 'Surveys homologous series nomenclature, petroleum fractional distillation, alkanes, alkenes, alcohols, carboxylic acids, and addition and condensation polymerisation.', 11, 8, 'hard', 13, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-chem-12', 'subj-caie-igcse-chem', 'Experimental techniques and chemical analysis', 'Details experimental measurement tools, acid-base titrations, paper chromatography, purification methods, and identification tests for ions and gases.', 12, 5, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-01', 'subj-caie-igcse-cs', 'Data representation', 'Covers binary, denary, and hexadecimal number systems, binary addition and shifts, two-complement representation, multimedia encoding, and data compression.', 1, 3, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-02', 'subj-caie-igcse-cs', 'Data transmission', 'Examines packet switching structures, serial/parallel data transmission methods, USB interfaces, error detection techniques, and symmetric/asymmetric encryption.', 2, 3, 'medium', 7, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-03', 'subj-caie-igcse-cs', 'Hardware', 'Details the Von Neumann computer architecture, the fetch-decode-execute cycle, input/output peripherals, data storage technologies, and network hardware.', 3, 4, 'medium', 9, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-04', 'subj-caie-igcse-cs', 'Software', 'Distinguishes between system and application software, outlines operating system functions, hardware interrupts, language translators, and IDE utilities.', 4, 2, 'easy', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-05', 'subj-caie-igcse-cs', 'The internet and its uses', 'Explores the structure of the World Wide Web, web browsers, cookies, digital currencies and blockchain, cybersecurity threats, and security solutions.', 5, 3, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-06', 'subj-caie-igcse-cs', 'Automated and emerging technologies', 'Examines automated monitoring and control loops, the principles and applications of robotics, and artificial intelligence architectures.', 6, 3, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-07', 'subj-caie-igcse-cs', 'Algorithm design and problem-solving', 'Focuses on the program development life cycle, problem decomposition, standard algorithms, validation and verification checks, test data, and trace tables.', 7, 1, 'hard', 11, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-08', 'subj-caie-igcse-cs', 'Programming', 'Covers procedural programming constructs, basic data types, sequence, selection, iteration, string handling, procedures, functions, arrays, and file handling.', 8, 3, 'hard', 15, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-09', 'subj-caie-igcse-cs', 'Databases', 'Examines single-table relational database structures, field definitions, primary keys, and writing Structured Query Language (SQL) data retrieval queries.', 9, 1, 'medium', 5, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-cs-10', 'subj-caie-igcse-cs', 'Boolean logic', 'Details logic gates, combinational logic circuits, truth tables, and constructing Boolean logic expressions from problem statements.', 10, 1, 'medium', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-eng-first-01', 'subj-caie-igcse-eng-first', 'Reading', 'Develops comprehension of explicit and implicit meanings, analyzing linguistic devices, evaluating attitudes, and selecting information across various text types.', 1, 6, 'medium', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-eng-first-02', 'subj-caie-igcse-eng-first', 'Writing', 'Builds skills in composing continuous prose across discursive, descriptive, narrative, and argumentative forms with accurate grammar, spelling, and register.', 2, 6, 'hard', 15, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-eng-first-03', 'subj-caie-igcse-eng-first', 'Speaking and Listening', 'Practices presenting structured individual talks, communicating fluently, engaging in spontaneous conversation, and demonstrating spoken language control.', 3, 6, 'easy', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-esl-01', 'subj-caie-igcse-esl', 'Reading', 'Focuses on skimming, scanning, locating specific facts, understanding implied opinions, and interpreting continuous informational and argumentative texts.', 1, 4, 'medium', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-esl-02', 'subj-caie-igcse-esl', 'Writing', 'Develops continuous prose writing for emails, reports, reviews, and articles using cohesive linking devices and appropriate formal or informal registers.', 2, 5, 'hard', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-esl-03', 'subj-caie-igcse-esl', 'Listening', 'Covers identifying key details, understanding attitudes and speakers viewpoints, and interpreting implied meaning across monologues and dialogues.', 3, 4, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-esl-04', 'subj-caie-igcse-esl', 'Speaking', 'Practices personal interview exchanges, delivering individual short talks on given topic cards, and actively participating in themed conversational discussions.', 4, 5, 'easy', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-econ-01', 'subj-caie-igcse-econ', 'The basic economic problem', 'Examines scarce resources versus infinite wants, factors of production, opportunity costs, and production possibility curve (PPC) models.', 1, 4, 'easy', 6, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-econ-02', 'subj-caie-igcse-econ', 'The allocation of resources', 'Covers the price mechanism, demand and supply curves, market equilibrium, price elasticity of demand and supply, market failure, and government intervention.', 2, 10, 'hard', 13, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-econ-03', 'subj-caie-igcse-econ', 'Microeconomic decision-makers', 'Analyses the roles of banks, households, and workers, wage determination, business structures, economies of scale, production costs, and market types.', 3, 7, 'hard', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-econ-04', 'subj-caie-igcse-econ', 'Government and the macroeconomy', 'Details government macroeconomic aims, fiscal, monetary, and supply-side policies, along with economic growth, unemployment, and inflation causes and effects.', 4, 7, 'hard', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-econ-05', 'subj-caie-igcse-econ', 'Economic development', 'Explores indicators of living standards including real GDP per head and HDI, causes of poverty, population demographics, and international development gaps.', 5, 4, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-caie-igcse-econ-06', 'subj-caie-igcse-econ', 'International trade and globalisation', 'Covers country specialisation, free trade, globalisation impacts, protectionism methods, foreign exchange rate determination, and current account balances.', 6, 4, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000);